:root {
  color-scheme: light;
  --canvas: var(--sya-canvas, #eef1ed);
  --surface: var(--sya-surface, #fcfdfb);
  --surface-muted: var(--sya-surface-muted, #e2e6e1);
  --text: var(--sya-text, #191b19);
  --text-secondary: var(--sya-text-secondary, #59605b);
  --border: var(--sya-border, #d9ddd9);
  --primary: var(--sya-primary, #252725);
  --primary-hover: var(--sya-primary-hover, #343734);
  --primary-foreground: var(--sya-primary-foreground, #f8faf8);
  --success: var(--sya-success, #18794e);
  --success-foreground: var(--sya-success-foreground, #ffffff);
  --success-surface: var(--sya-success-surface, #e7f6ec);
  --success-surface-foreground: var(--sya-success-surface-foreground, #17653f);
  --warning: var(--sya-warning, #946200);
  --warning-foreground: var(--sya-warning-foreground, #ffffff);
  --warning-surface: var(--sya-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #6b4600);
  --danger: var(--sya-danger, #b42318);
  --danger-foreground: var(--sya-danger-foreground, #ffffff);
  --danger-surface: var(--sya-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #8f1d14);
  --focus: var(--sya-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--sya-canvas, #121412);
    --surface: var(--sya-surface, #1a1d1a);
    --surface-muted: var(--sya-surface-muted, #232623);
    --text: var(--sya-text, #f1f3f0);
    --text-secondary: var(--sya-text-secondary, #afb5b0);
    --border: var(--sya-border, #373b37);
    --primary: var(--sya-primary, #ecefeb);
    --primary-hover: var(--sya-primary-hover, #ffffff);
    --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
    --success: var(--sya-success, #62c98f);
    --success-foreground: var(--sya-success-foreground, #092416);
    --success-surface: var(--sya-success-surface, #173526);
    --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
    --warning: var(--sya-warning, #e9ad45);
    --warning-foreground: var(--sya-warning-foreground, #291900);
    --warning-surface: var(--sya-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
    --danger: var(--sya-danger, #ff716b);
    --danger-foreground: var(--sya-danger-foreground, #260503);
    --danger-surface: var(--sya-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
    --focus: var(--sya-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--sya-canvas, #121412);
  --surface: var(--sya-surface, #1a1d1a);
  --surface-muted: var(--sya-surface-muted, #232623);
  --text: var(--sya-text, #f1f3f0);
  --text-secondary: var(--sya-text-secondary, #afb5b0);
  --border: var(--sya-border, #373b37);
  --primary: var(--sya-primary, #ecefeb);
  --primary-hover: var(--sya-primary-hover, #ffffff);
  --primary-foreground: var(--sya-primary-foreground, #1b1d1b);
  --success: var(--sya-success, #62c98f);
  --success-foreground: var(--sya-success-foreground, #092416);
  --success-surface: var(--sya-success-surface, #173526);
  --success-surface-foreground: var(--sya-success-surface-foreground, #8ee0ae);
  --warning: var(--sya-warning, #e9ad45);
  --warning-foreground: var(--sya-warning-foreground, #291900);
  --warning-surface: var(--sya-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--sya-warning-surface-foreground, #f2c66f);
  --danger: var(--sya-danger, #ff716b);
  --danger-foreground: var(--sya-danger-foreground, #260503);
  --danger-surface: var(--sya-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--sya-danger-surface-foreground, #ffaaa5);
  --focus: var(--sya-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .sya-code-source .shiki,
html[data-theme="dark"] .sya-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .sya-code-source .shiki,
  html:not([data-theme="light"]) .sya-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes sya-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes sya-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes sya-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type MouseEvent,
} from "react";
import { animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface TableOfContentsItem {
  id: string;
  label: string;
}

export interface TableOfContentsProps {
  items: TableOfContentsItem[];
  title?: string;
  ariaLabel?: string;
}

export function TableOfContents({
  items,
  title = "On this page",
  ariaLabel = "On this page",
}: TableOfContentsProps) {
  const [observedActiveId, setObservedActiveId] = useState(items[0]?.id ?? "");
  const activeId = items.some((item) => item.id === observedActiveId)
    ? observedActiveId
    : (items[0]?.id ?? "");
  const listRef = useRef<HTMLUListElement>(null);
  const itemRefs = useRef(new Map<string, HTMLLIElement>());
  const railReady = useRef(false);
  const clickedIdRef = useRef<string>("");
  const clickLockTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const reduceMotion = useReducedMotion() ?? false;
  const railY = useMotionValue(0);
  const railHeight = useMotionValue(0);
  const railOpacity = useMotionValue(0);

  const selectItem = (event: MouseEvent<HTMLAnchorElement>, id: string) => {
    setObservedActiveId(id);

    if (
      event.defaultPrevented ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey
    ) {
      return;
    }

    const section = document.getElementById(id);
    if (!section) return;

    event.preventDefault();
    clickedIdRef.current = id;
    clearTimeout(clickLockTimerRef.current);
    clickLockTimerRef.current = setTimeout(() => {
      clickedIdRef.current = "";
    }, 2000);
    window.history.pushState(null, "", `#${encodeURIComponent(id)}`);
    section.scrollIntoView({
      behavior: reduceMotion ? "auto" : "smooth",
      block: "start",
    });
  };

  useEffect(() => {
    if (!items.length) return;
    let frame = 0;
    let releaseFrame = 0;

    const update = () => {
      if (clickedIdRef.current) {
        setObservedActiveId(clickedIdRef.current);
        return;
      }

      let current = items[0]?.id ?? "";

      for (const item of items) {
        const section = document.getElementById(item.id);
        if (section && section.getBoundingClientRect().top <= 128) {
          current = item.id;
        }
      }

      const pageHeight = document.documentElement.scrollHeight;
      const reachedPageEnd =
        pageHeight > window.innerHeight + 2 &&
        window.innerHeight + window.scrollY >= pageHeight - 2;
      if (reachedPageEnd) current = items.at(-1)?.id ?? current;

      setObservedActiveId(current);
    };

    const onScroll = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(update);
    };
    const releaseClickLock = () => {
      clearTimeout(clickLockTimerRef.current);
      cancelAnimationFrame(releaseFrame);
      releaseFrame = requestAnimationFrame(() => {
        clickedIdRef.current = "";
      });
    };

    frame = requestAnimationFrame(update);
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("scrollend", releaseClickLock);

    return () => {
      cancelAnimationFrame(frame);
      cancelAnimationFrame(releaseFrame);
      clearTimeout(clickLockTimerRef.current);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("scrollend", releaseClickLock);
    };
  }, [items]);

  useLayoutEffect(() => {
    const list = listRef.current;
    const item = itemRefs.current.get(activeId);

    if (!list || !item) {
      railReady.current = false;
      railOpacity.jump(0);
      return;
    }

    const listRect = list.getBoundingClientRect();
    const itemRect = item.getBoundingClientRect();
    const nextY = itemRect.top - listRect.top;
    const transition = reduceMotion
      ? { duration: 0 }
      : motionTokens.spring.morph;

    if (!railReady.current || reduceMotion) {
      railY.jump(nextY);
      railHeight.jump(itemRect.height);
    } else {
      animate(railY, nextY, transition);
      animate(railHeight, itemRect.height, transition);
    }

    railReady.current = true;
    railOpacity.jump(1);
  }, [activeId, items, railHeight, railOpacity, railY, reduceMotion]);

  if (!items.length) return null;

  return (
    <nav className="min-w-0" aria-label={ariaLabel}>
      <p className="text-xs font-[650] text-[var(--text)]">{title}</p>
      <div className="relative mt-3.5">
        <span className="pointer-events-none absolute top-0 bottom-0 left-0 w-px bg-[var(--border)]" aria-hidden="true" />
        <motion.span
          className="pointer-events-none absolute top-0 left-0 z-[1] w-0.5 rounded-full bg-[var(--text)]"
          style={{ y: railY, height: railHeight, opacity: railOpacity }}
          aria-hidden="true"
        />
        <ul className="m-0 grid list-none gap-[3px] p-0 pl-[13px]" ref={listRef}>
          {items.map((item) => (
            <li
              ref={(element) => {
                if (element) itemRefs.current.set(item.id, element);
                else itemRefs.current.delete(item.id);
              }}
              key={item.id}
            >
              <a
                className={
                  activeId === item.id ? "block rounded-md px-0.5 py-[5px] text-xs leading-[1.35] no-underline text-[var(--text)] transition-colors duration-[var(--duration-fast)] ease-[var(--ease-standard)] hover:text-[var(--text)] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-2" : "block rounded-md px-0.5 py-[5px] text-xs leading-[1.35] no-underline text-[var(--text-secondary)] transition-colors duration-[var(--duration-fast)] ease-[var(--ease-standard)] hover:text-[var(--text)] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-2"
                }
                href={`#${item.id}`}
                aria-current={activeId === item.id ? "location" : undefined}
                onClick={(event) => selectItem(event, item.id)}
              >
                {item.label}
              </a>
            </li>
          ))}
        </ul>
      </div>
    </nav>
  );
}
